    "code": "module uart_tx (\r\n    input  wire       clk,\r\n    input  wire       rst,\r\n    input  wire       tx_start,\r\n    input  wire [7:0] tx_data,\r\n    input  wire       baud_tick,\r\n    output reg        tx,\r\n    output reg        tx_busy,\r\n    output reg        tx_done\r\n);\r\n\r\n    localparam [2:0] IDLE       = 3'd0;\r\n    localparam [2:0] START_WAIT = 3'd1;\r\n    localparam [2:0] START_BIT  = 3'd2;\r\n    localparam [2:0] DATA       = 3'd3;\r\n    localparam [2:0] STOP_BIT   = 3'd4;\r\n    localparam [2:0] STOP_HOLD  = 3'd5;\r\n\r\n    reg [2:0] state;\r\n    reg [7:0] shift_reg;\r\n    reg [2:0] bit_index;\r\n\r\n    always @(posedge clk or posedge rst) begin\r\n        if (rst) begin\r\n            state     <= IDLE;\r\n            shift_reg <= 8'b0;\r\n            bit_index <= 3'b0;\r\n            tx        <= 1'b1;\r\n            tx_busy   <= 1'b0;\r\n            tx_done   <= 1'b0;\r\n        end\r\n        else begin\r\n            tx_done <= 1'b0;\r\n\r\n            case (state)\r\n                IDLE: begin\r\n                    tx      <= 1'b1;\r\n                    tx_busy <= 1'b0;\r\n                    if (tx_start) begin\r\n                        shift_reg <= tx_data;\r\n                        bit_index <= 3'd0;\r\n                        tx_busy   <= 1'b1;\r\n                        state     <= START_WAIT;\r\n                    end\r\n                end\r\n\r\n                START_WAIT: begin\r\n                    if (baud_tick) begin\r\n                        tx    <= 1'b0;\r\n                        state <= START_BIT;\r\n                    end\r\n                end\r\n\r\n                START_BIT: begin\r\n                    if (baud_tick) begin\r\n                        tx        <= shift_reg[0];\r\n                        shift_reg <= {1'b0, shift_reg[7:1]};\r\n                        bit_index <= 3'd1;\r\n                        state     <= DATA;\r\n                    end\r\n                end\r\n\r\n                DATA: begin\r\n                    if (baud_tick) begin\r\n                        tx        <= shift_reg[0];\r\n                        shift_reg <= {1'b0, shift_reg[7:1]};\r\n\r\n                        if (bit_index == 3'd7)\r\n                            state <= STOP_BIT;\r\n                        else\r\n                            bit_index <= bit_index + 1'b1;\r\n                    end\r\n                end\r\n\r\n                STOP_BIT: begin\r\n                    if (baud_tick) begin\r\n                        tx    <= 1'b1;\r\n                        state <= STOP_HOLD;\r\n                    end\r\n                end\r\n\r\n                STOP_HOLD: begin\r\n                    if (baud_tick) begin\r\n                        tx      <= 1'b1;\r\n                        tx_busy <= 1'b0;\r\n                        tx_done <= 1'b1;\r\n                        state   <= IDLE;\r\n                    end\r\n                end\r\n\r\n                default: begin\r\n                    state   <= IDLE;\r\n                    tx      <= 1'b1;\r\n                    tx_busy <= 1'b0;\r\n                    tx_done <= 1'b0;\r\n                end\r\n            endcase\r\n        end\r\n    end\r\n\r\nendmodule",
